import json, sys
lines = [json.loads(l) for l in sys.stdin if l.strip()]

selected = []

# 策略：每个维度保留2-3个case，覆盖不同dtype和attr
# 1D: 小shape + 不同dtype/attr
for case in lines:
    inp = case['inputs']
    s, d, a = inp[0]['shape'], inp[0]['dtype'], inp[1]['value']
    if len(s) == 1 and s == [128] and d == 'float32' and a == False:
        selected.append(case); break
for case in lines:
    inp = case['inputs']
    s, d, a = inp[0]['shape'], inp[0]['dtype'], inp[1]['value']
    if len(s) == 1 and s == [256] and d == 'int64' and a == True:
        selected.append(case); break

# 2D: 中等shape
for case in lines:
    inp = case['inputs']
    s, d, a = inp[0]['shape'], inp[0]['dtype'], inp[1]['value']
    if len(s) == 2 and s == [128, 256] and d == 'float32' and a == False:
        selected.append(case); break
for case in lines:
    inp = case['inputs']
    s, d, a = inp[0]['shape'], inp[0]['dtype'], inp[1]['value']
    if len(s) == 2 and s == [512, 1024] and d == 'float16' and a == False:
        selected.append(case); break

# 3D
for case in lines:
    inp = case['inputs']
    s, d, a = inp[0]['shape'], inp[0]['dtype'], inp[1]['value']
    if len(s) == 3 and s == [64, 128, 256] and d == 'float32' and a == False:
        selected.append(case); break
for case in lines:
    inp = case['inputs']
    s, d, a = inp[0]['shape'], inp[0]['dtype'], inp[1]['value']
    if len(s) == 3 and s == [8, 256, 512] and d == 'bfloat16' and a == True:
        selected.append(case); break

# 4D
for case in lines:
    inp = case['inputs']
    s, d, a = inp[0]['shape'], inp[0]['dtype'], inp[1]['value']
    if len(s) == 4 and s == [1, 64, 128, 128] and d == 'float32' and a == False:
        selected.append(case); break
for case in lines:
    inp = case['inputs']
    s, d, a = inp[0]['shape'], inp[0]['dtype'], inp[1]['value']
    if len(s) == 4 and s == [1, 256, 32, 32] and d == 'float16' and a == False:
        selected.append(case); break

# 补充: int32 + 大shape极端
for case in lines:
    inp = case['inputs']
    s, d, a = inp[0]['shape'], inp[0]['dtype'], inp[1]['value']
    if len(s) == 2 and s == [64, 128] and d == 'int32' and a == False:
        selected.append(case); break

# 补充: 大shape 2D
for case in lines:
    inp = case['inputs']
    s, d, a = inp[0]['shape'], inp[0]['dtype'], inp[1]['value']
    if len(s) == 2 and s == [5120, 27648] and d == 'float16' and a == True:
        selected.append(case); break

print(f'Selected: {len(selected)}')
for i, c in enumerate(selected):
    inp = c['inputs']
    print(f'  {i}: shape={inp[0][\"shape\"]}, dtype={inp[0][\"dtype\"]}, attr={inp[1][\"value\"]}')

# 写回
with open('./0626/local_baseline_runs_pass1/22_Nonzero/22_Nonzero.json', 'w') as f:
    for case in selected:
        f.write(json.dumps(case) + '\n')
print('Written to 22_Nonzero.json')
