#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_nonzero.h"
#include <torch/extension.h>
#include <ATen/ATen.h>

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor nonzero(const at::Tensor& self, int64_t as_tuple) {
    // ---- 输入校验 ----
    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
                "nonzero: input must be on NPU device");

    int64_t ndim = self.dim();
    int64_t totalLength = self.numel();

    if (totalLength == 0) {
        if (as_tuple) {
            // Return tuple of empty tensors
            std::vector<at::Tensor> result;
            for (int64_t i = 0; i < ndim; i++) {
                result.push_back(at::empty({0}, at::TensorOptions().dtype(at::kLong).device(self.device())));
            }
            // We can't return tuple from this function, so return empty 2D tensor
            // The Python wrapper will handle as_tuple conversion
            return at::empty({0, ndim}, at::TensorOptions().dtype(at::kLong).device(self.device()));
        }
        return at::empty({0, ndim}, at::TensorOptions().dtype(at::kLong).device(self.device()));
    }

    // ---- 获取平台参数 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // ---- 连续化 ----
    at::Tensor selfContiguous = self.contiguous();
    int64_t dtypeSize = selfContiguous.element_size();

    // ---- Block 级 Tiling ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = ((totalLengthCore * dtypeSize + CACHE_LINE_BYTE_LENGTH - 1)
                                     / CACHE_LINE_BYTE_LENGTH) * CACHE_LINE_BYTE_LENGTH;
    int64_t usedCoreNum = (totalLength * dtypeSize + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    if (usedCoreNum > coreNum) usedCoreNum = coreNum;
    if (usedCoreNum < 1) usedCoreNum = 1;

    int64_t formerNum = usedCoreNum - 1;
    if (formerNum < 0) formerNum = 0;
    int64_t tailNum = 1;
    int64_t formerLength = totalLengthCoreAlign / dtypeSize;
    int64_t tailLength = totalLength - formerNum * formerLength;
    if (tailLength < 0) {
        tailLength = 0;
        tailNum = 0;
    }

    // ---- 第一阶段：统计每个核的非零元素数 ----
    // We do this on CPU since we need the count to allocate output
    // For small tensors this is efficient; for large tensors we could use a kernel
    auto selfCpu = selfContiguous.to(at::kCPU);
    int64_t nonzeroCount = 0;

    // Simple CPU count - works for all dtypes
    AT_DISPATCH_ALL_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16,
        selfCpu.scalar_type(), "nonzero_count", [&]() {
        scalar_t* data = selfCpu.data_ptr<scalar_t>();
        for (int64_t i = 0; i < totalLength; i++) {
            if (data[i] != scalar_t(0)) {
                nonzeroCount++;
            }
        }
    });

    // ---- 分配输出 ----
    auto output = at::empty({nonzeroCount, ndim},
                             at::TensorOptions().dtype(at::kLong).device(self.device()));

    if (nonzeroCount == 0) {
        if (as_tuple) {
            // Return tuple of empty tensors - handled in Python wrapper
        }
        return output;
    }

    // ---- 计算每个核的输出偏移（prefix sum） ----
    // For simplicity, we compute per-core counts on CPU and do prefix sum
    std::vector<int64_t> coreCounts(usedCoreNum, 0);
    std::vector<int64_t> coreOffsets(usedCoreNum, 0);

    AT_DISPATCH_ALL_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16,
        selfCpu.scalar_type(), "nonzero_per_core_count", [&]() {
        scalar_t* data = selfCpu.data_ptr<scalar_t>();
        for (int64_t c = 0; c < usedCoreNum; c++) {
            int64_t start = (c < formerNum) ? c * formerLength
                                             : formerNum * formerLength + (c - formerNum) * tailLength;
            int64_t len = (c < formerNum) ? formerLength : tailLength;
            if (start >= totalLength) {
                coreCounts[c] = 0;
                continue;
            }
            if (start + len > totalLength) {
                len = totalLength - start;
            }
            int64_t count = 0;
            for (int64_t i = start; i < start + len; i++) {
                if (data[i] != scalar_t(0)) count++;
            }
            coreCounts[c] = count;
        }
    });

    // Prefix sum for offsets
    int64_t offset = 0;
    for (int64_t c = 0; c < usedCoreNum; c++) {
        coreOffsets[c] = offset;
        offset += coreCounts[c];
    }

    // ---- UB 级 Tiling ----
    int64_t bufferCoefficient = 2;  // Only inQueueX double buffer
    int64_t maxTileElements = static_cast<int64_t>(ubSize) / dtypeSize / bufferCoefficient;
    int64_t alignElements = 32 / dtypeSize;
    if (alignElements < 1) alignElements = 1;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength < 1) tileLength = 1;

    // ---- Workspace: store shape info ----
    int64_t workspaceSize = (8 + 8) * sizeof(int64_t);  // shape[8] + strides[8]
    auto workspace = at::empty({workspaceSize},
                               at::TensorOptions().dtype(at::kByte).device(self.device()));
    auto workspaceCpu = at::empty({workspaceSize}, at::TensorOptions().dtype(at::kByte));
    int64_t* workspaceData = reinterpret_cast<int64_t*>(workspaceCpu.data_ptr<uint8_t>());
    for (int64_t i = 0; i < ndim; i++) {
        workspaceData[i] = selfContiguous.size(i);
    }
    for (int64_t i = ndim; i < 8; i++) {
        workspaceData[i] = 1;
    }
    workspace.copy_(workspaceCpu);

    // ---- 启动 Kernel ----
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    if (blockDim < 1) blockDim = 1;

    // Left-value variables for EXEC_KERNEL_CMD
    int64_t totalLengthL = totalLength;
    int64_t ndimL = ndim;
    int64_t formerNumL = formerNum;
    int64_t formerLengthL = formerLength;
    int64_t tailNumL = tailNum;
    int64_t tailLengthL = tailLength;
    int64_t tileLengthL = tileLength;

    for (int64_t c = 0; c < usedCoreNum; c++) {
        int64_t outOffsetL = coreOffsets[c];
        // We launch kernel per core with its specific offset
        // Actually, EXEC_KERNEL_CMD launches all cores together
        // We need to pass all offsets via workspace or tiling
        // For simplicity, we pass the offset array in workspace
    }

    // Store offsets in workspace after shape data
    for (int64_t c = 0; c < usedCoreNum && c < 8; c++) {
        workspaceData[8 + c] = coreOffsets[c];
    }
    workspace.copy_(workspaceCpu);

    // Pass all offsets through workspace - kernel reads its own offset
    EXEC_KERNEL_CMD(nonzero, blockDim, selfContiguous, output, workspace,
                    totalLengthL, ndimL, formerNumL, formerLengthL,
                    tailNumL, tailLengthL, tileLengthL, 0);

    return output;
}

}  // namespace ascend_kernel
