    auto workspaceCpu = at::empty({workspaceSize}, at::TensorOptions().dtype(at::kByte));
    int64_t* workspaceData = reinterpret_cast<int64_t*>(workspaceCpu.data_ptr<uint8_t>());
    for (int64_t i = 0; i < ndim; i++) {
        workspaceData[i] = selfContiguous.size(i);
    }
    for (int64_t i = ndim; i < 8; i++) {
        workspaceData[i] = 1;
    }
    for (int64_t c = 0; c < usedCoreNum; c++) {
        workspaceData[8 + c] = coreOffsets[c];
    }
    workspace.copy_(workspaceCpu);

    // ---- Launch Kernel ----
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    if (blockDim < 1) blockDim = 1;

    int64_t totalLengthL = totalLength;
    int64_t ndimL = ndim;
    int64_t formerNumL = formerNum;
    int64_t formerLengthL = formerLength;
    int64_t tailNumL = tailNum;
    int64_t tailLengthL = tailLength;
    int64_t tileLengthL = tileLength;

    EXEC_KERNEL_CMD(nonzero, blockDim, selfContiguous, output, workspace,
                    totalLengthL, ndimL, formerNumL, formerLengthL,
                    tailNumL, tailLengthL, tileLengthL);

