        GlobalTensor<int64_t> workspaceGm;
        workspaceGm.SetGlobalBuffer((__gm__ int64_t*)workspace);
        for (int64_t i = 0; i < ndim_ && i < 8; i++) {
            shape_[i] = workspaceGm.GetValue(i);
        }

        // Read offsets from workspace (after shape, starting at index 8)
        int64_t blockIdx = GetBlockIdx();
        if (blockIdx < formerNum_ + tailNum_) {
            outOffset_ = workspaceGm.GetValue(8 + blockIdx);
        } else {
            outOffset_ = 0;
        }

        // Calculate block start and length for this core
        if (blockIdx < formerNum_) {
            blockLength_ = formerLength_;
            blockStart_ = blockIdx * formerLength_;
        } else if (blockIdx < formerNum_ + tailNum_) {
            blockLength_ = tailLength_;
            blockStart_ = formerNum_ * formerLength_ + (blockIdx - formerNum_) * tailLength_;
        } else {
            blockLength_ = 0;
            blockStart_ = 0;
        }

        writePos_ = outOffset_;

        // Init input buffer
        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength_ * sizeof(T));
    }

    __aicore__ inline void Process()
    {
        if (blockLength_ == 0) return;

        int64_t tileNum = (blockLength_ + tileLength_ - 1) / tileLength_;
        int64_t tailTileLength = blockLength_ - (tileNum - 1) * tileLength_;

        for (int64_t i = 0; i < tileNum; i++) {
            int64_t curTileLength = (i == tileNum - 1) ? tailTileLength : tileLength_;
            CopyIn(i, curTileLength);
            Compute(i, curTileLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(curTileLength * sizeof(T));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        DataCopyPadExtParams<T> padParams;
        padParams.isPad = false;
        DataCopyPad(xLocal, selfGm[blockStart_ + progress * tileLength_], copyParams, padParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        LocalTensor<T> xLocal = inQueueX.DeQue<T>();

        for (int64_t i = 0; i < curTileLength; i++) {
            T val = xLocal.GetValue(i);
            bool isNonzero = false;

            if constexpr (std::is_same_v<T, float> || std::is_same_v<T, half> || std::is_same_v<T, bfloat16_t>) {
                isNonzero = (val != static_cast<T>(0));
            } else {
                isNonzero = (val != 0);
            }

            if (isNonzero) {
                int64_t flat = blockStart_ + progress * tileLength_ + i;

                // Convert flat index to multi-dimensional index
                for (int64_t d = ndim_ - 1; d >= 0; d--) {
                    int64_t idx = flat % shape_[d];
                    flat /= shape_[d];
                    outGm.SetValue(writePos_ * ndim_ + d, idx);
                }
                writePos_++;
            }
        }

        inQueueX.FreeTensor(xLocal);
    }

private:
    TPipe pipe;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueueX;

    GlobalTensor<T> selfGm;
    GlobalTensor<int64_t> outGm;

    int64_t totalLength_ = 0;
    int64_t ndim_ = 0;
    int64_t formerNum_ = 0;
    int64_t formerLength_ = 0;
    int64_t tailNum_ = 0;
    int64_t tailLength_ = 0;
    int64_t tileLength_ = 0;
    int64_t blockLength_ = 0;
    int64_t blockStart_ = 0;
    int64_t outOffset_ = 0;
    int64_t writePos_ = 0;
    int64_t shape_[8];
};

extern "C" __global__ __aicore__ void nonzero(GM_ADDR self, GM_ADDR out, GM_ADDR workspace,
                                                int64_t totalLength, int64_t ndim,
                                                int64_t formerNum, int64_t formerLength,
                                                int64_t tailNum, int64_t tailLength,
                                                int64_t tileLength)
{
    if (totalLength > 0) {
        NonzeroKernel<float> op;
        op.Init(self, out, workspace, totalLength, ndim,
                formerNum, formerLength, tailNum, tailLength, tileLength);
        op.Process();
    }
}
