19	at::Tensor gelu(const at::Tensor &self, const std::string &approximate)
20	{
21	    // ---- 输入校验 ----
22	    TORCH_CHECK(self.scalar_type() == at::kHalf ||
23	                self.scalar_type() == at::kFloat ||
24	                self.scalar_type() == at::kBFloat16,
25	                "gelu: only float16, bfloat16 and float32 are supported, got ", self.scalar_type());
26	
27	    at::Tensor output = at::empty_like(self);
28	
29	    int64_t totalLength = self.numel();
30	    if (totalLength == 0) {
31	        return output;
32	    }
33	
34	    // Convert approximate string to int
35	    int64_t approxInt = (approximate == "tanh") ? 1 : 0;
36	
37	    // For non-float32 inputs, convert to float32 on host, compute, then convert back
38	    bool needCast = (self.scalar_type() != at::kFloat);
39	    at::Tensor inputFloat = needCast ? self.to(at::kFloat) : self;
40	    at::Tensor outputFloat = needCast ? at::empty_like(inputFloat) : output;
41	
42	    int64_t dtypeSize = 4; // Always float32 in kernel
43	
44	    // ---- 获取硬件参数 ----
45	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
46	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
47	    uint64_t ubSize;
48	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
49	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
50	
51	    // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
52	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
53	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
54	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
55	
56	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
57	    int64_t formerNum = usedCoreNum - 1;
58	    int64_t formerLength = totalLengthCoreAlign;
59	    int64_t tailLength = totalLength - formerNum * formerLength;
60	
61	    // ---- UB 级 tiling (核内切分) ----
62	    int64_t bufferCoefficient = 20; // float32
63	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
64	    int64_t alignElements = 32 / dtypeSize; // 8 for float32
65	    if (alignElements == 0) { alignElements = 1; }
66	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
67	    if (tileLength < alignElements) {
68	        tileLength = alignElements;
69	    }
70	
71	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
72	
73	    // EXEC_KERNEL_CMD: all args must be left values
74	    int64_t dtypeSizeLval = dtypeSize;
75	    int64_t approxIntLval = approxInt;
76	    int64_t formerNumLval = formerNum;
77	    int64_t formerLengthLval = formerLength;
78	    int64_t tailLengthLval = tailLength;
79	    int64_t tileLengthLval = tileLength;
80	    void* workspace = nullptr;
81	
82	    EXEC_KERNEL_CMD(gelu, blockDim,
83	                    inputFloat, outputFloat, workspace,
84	                    formerNumLval, formerLengthLval, tailLengthLval, tileLengthLval,
85	                    dtypeSizeLval, approxIntLval);
86	
87	    if (needCast) {
88	        output.copy_(outputFloat);
89	    }
90	
91	    return output;
92	}
