12	
13	constexpr int32_t BUFFER_NUM = 2;
14	
15	// GELU constants for tanh approximation
16	constexpr float SQRT_2_OVER_PI = 0.7978845608f;
17	constexpr float GELU_COEFF = 0.044715f;
18	constexpr float HALF = 0.5f;
19	constexpr float ONE = 1.0f;
20	constexpr float SQRT_2 = 1.4142135624f;
21	
22	// Scalar exp with range reduction for better accuracy
23	// exp(x) = 2^k * exp(r) where x = k*ln(2) + r, |r| < ln(2)/2
24	__aicore__ inline float scalar_exp(float x)
25	{
26	    // For negative x, compute exp(x) = 1/exp(-x)
27	    bool neg = x < 0;
28	    float abs_x = neg ? -x : x;
29	
30	    // Range reduction: exp(abs_x) = 2^k * exp(r)
31	    // k = floor(abs_x / ln(2)), r = abs_x - k*ln(2)
32	    float ln2 = 0.69314718056f;
33	    int k = static_cast<int>(abs_x / ln2);
34	    float r = abs_x - k * ln2;
35	
36	    // Taylor series for exp(r) where |r| < ln(2) ≈ 0.693
37	    // 10th order is sufficient for |r| < 0.7
38	    float r2 = r * r;
39	    float r3 = r2 * r;
40	    float r4 = r2 * r2;
41	    float r5 = r4 * r;
42	    float r6 = r4 * r2;
43	    float r7 = r6 * r;
44	    float r8 = r4 * r4;
45	
46	    float exp_r = 1.0f + r
47	        + r2 * 0.5f
48	        + r3 * 0.1666666667f
49	        + r4 * 0.0416666667f
50	        + r5 * 0.0083333333f
51	        + r6 * 0.0013888889f
52	        + r7 * 0.0001984127f
53	        + r8 * 0.0000248016f
54	        + r8 * r * 0.0000027557f
55	        + r8 * r2 * 0.0000002756f;
56	
57	    // 2^k = 1 << k for integer k, or use repeated squaring
58	    float pow2 = 1.0f;
59	    for (int i = 0; i < k; ++i) {
60	        pow2 *= 2.0f;
61	    }
62	
63	    float result = pow2 * exp_r;
64	
65	    if (neg) {
66	        result = 1.0f / result;
67	    }
68	    return result;
69	}
70	
71	// Scalar tanh using exp approximation
72	__aicore__ inline float scalar_tanh(float x)
73	{
74	    float exp2x = scalar_exp(2.0f * x);
75	    return (exp2x - 1.0f) / (exp2x + 1.0f);
76	}
77	
78	// Higher precision erf approximation using tanh-based formula
79	// erf(x) ≈ tanh(1.128379*x + 0.102*x^3) with better accuracy than A&S 7.1.26
80	__aicore__ inline float scalar_erf(float x)
81	{
82	    float abs_x = x >= 0 ? x : -x;
83	    float x3 = abs_x * abs_x * abs_x;
84	    float tanh_input = 1.1283791670955126f * abs_x + 0.102f * x3;
85	    float exp2x = scalar_exp(2.0f * tanh_input);
86	    float erf_val = (exp2x - 1.0f) / (exp2x + 1.0f);
87	    return x >= 0 ? erf_val : -erf_val;
88	}
