90	class KernelGELU {
91	public:
92	    __aicore__ inline KernelGELU() {}
93	
94	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR workspace,
95	                                int64_t formerNum, int64_t formerLength,
96	                                int64_t tailLength, int64_t tileLength,
97	                                int64_t approximate)
98	    {
99	        int64_t blockIdx = AscendC::GetBlockIdx();
100	
101	        if (blockIdx < formerNum) {
102	            this->blockLength = formerLength;
103	            int64_t offset = formerLength * blockIdx;
104	            xGm.SetGlobalBuffer((__gm__ float *)x + offset, formerLength);
105	            yGm.SetGlobalBuffer((__gm__ float *)y + offset, formerLength);
106	        } else {
107	            this->blockLength = tailLength;
108	            int64_t tailIdx = blockIdx - formerNum;
109	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
110	            xGm.SetGlobalBuffer((__gm__ float *)x + offset, tailLength);
111	            yGm.SetGlobalBuffer((__gm__ float *)y + offset, tailLength);
112	        }
113	
114	        if (this->blockLength == 0) {
115	            return;
116	        }
117	
118	        this->tileLength = tileLength;
119	        this->approximate = approximate;
120	
121	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(float));
122	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(float));
123	    }
124	
125	    __aicore__ inline void Process()
126	    {
127	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
128	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
129	
130	        for (int64_t i = 0; i < tileNum - 1; ++i) {
131	            CopyIn(i, this->tileLength);
132	            Compute(i, this->tileLength);
133	            CopyOut(i, this->tileLength);
134	        }
135	        if (tileNum > 0) {
136	            CopyIn(tileNum - 1, tailTileLength);
137	            Compute(tileNum - 1, tailTileLength);
138	            CopyOut(tileNum - 1, tailTileLength);
139	        }
140	    }
141	
142	private:
143	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
144	    {
145	        AscendC::LocalTensor<float> xLocal = inQueueX.AllocTensor<float>();
146	        AscendC::DataCopyExtParams copyParams;
147	        copyParams.blockCount = 1;
148	        copyParams.blockLen = curTileLength * sizeof(float);
149	        copyParams.srcStride = 0;
150	        copyParams.dstStride = 0;
151	        AscendC::DataCopyPadExtParams<float> padParams(false, 0, 0, 0);
152	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams, padParams);
153	        inQueueX.EnQue(xLocal);
154	    }
155	
156	    __aicore__ inline float gelu_none(float x)
157	    {
158	        // GELU exact: x * 0.5 * (1 + erf(x / sqrt(2)))
159	        float erf_val = scalar_erf(x / SQRT_2);
160	        return x * HALF * (ONE + erf_val);
161	    }
162	
163	    __aicore__ inline float gelu_tanh(float x)
164	    {
165	        // GELU tanh approximation: 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
166	        float x3 = x * x * x;
167	        float inner = x + GELU_COEFF * x3;
168	        float tanh_input = SQRT_2_OVER_PI * inner;
169	        float tanh_val = scalar_tanh(tanh_input);
170	        return HALF * x * (ONE + tanh_val);
171	    }
172	
173	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
174	    {
175	        AscendC::LocalTensor<float> xLocal = inQueueX.DeQue<float>();
176	        AscendC::LocalTensor<float> yLocal = outQueueY.AllocTensor<float>();
177	
178	        uint32_t count = static_cast<uint32_t>(curTileLength);
179	
180	        for (uint32_t i = 0; i < count; ++i) {
181	            float x_val = xLocal.GetValue(i);
182	            float y_val;
183	            if (this->approximate == 0) {
184	                y_val = gelu_none(x_val);
185	            } else {
186	                y_val = gelu_tanh(x_val);
187	            }
188	            yLocal.SetValue(i, y_val);
189	        }
190	
191	        outQueueY.EnQue<float>(yLocal);
192	        inQueueX.FreeTensor(xLocal);
193	    }
194	
195	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
196	    {
197	        AscendC::LocalTensor<float> yLocal = outQueueY.DeQue<float>();
198	        AscendC::DataCopyExtParams copyParams;
199	        copyParams.blockCount = 1;
200	        copyParams.blockLen = curTileLength * sizeof(float);
201	        copyParams.srcStride = 0;
202	        copyParams.dstStride = 0;
203	        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
204	        outQueueY.FreeTensor(yLocal);
205	    }
206	
207	private:
208	    AscendC::TPipe pipe;
209	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
210	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
211	    AscendC::GlobalTensor<float> xGm;
212	    AscendC::GlobalTensor<float> yGm;
213	    int64_t blockLength;
214	    int64_t tileLength;
215	    int64_t approximate;
216	};
217	
218	extern "C" __global__ __aicore__ void gelu(GM_ADDR x, GM_ADDR y, GM_ADDR workspace,
219	                                            int64_t formerNum, int64_t formerLength,
220	                                            int64_t tailLength, int64_t tileLength,
221	                                            int64_t dtypeSize, int64_t approximate)
222	{
223	    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);
224	    if ASCEND_IS_AIV {
225	        KernelGELU op;
226	        op.Init(x, y, workspace, formerNum, formerLength, tailLength, tileLength, approximate);
227	        op.Process();
228	    }
229	}
