from pathlib import Path

import torch
import torch.nn as nn

_KERNEL_BUILD = Path(__file__).resolve().parent / "kernel" / "build"
_LIB_PATTERN = str(_KERNEL_BUILD / "nonzero_ext*.so")

# 优先 whl import（触发 TORCH_LIBRARY 注册）
try:
    import nonzero_ext  # noqa: F401
except ImportError:
    # 兜底：直加载 .so
    if _LIB_PATTERN not in "".join(sys.path):
        import glob as _glob
        _libs = _glob.glob(_LIB_PATTERN)
        if _libs:
            torch.ops.load_library(_libs[0])


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor, as_tuple: bool = False):
        # 调用注册的算子
        result = torch.ops.npu.nonzero(x, int(as_tuple))
        if as_tuple:
            # 将 2D 结果转为 tuple of 1D tensors
            ndim = x.dim()
            if result.shape[0] == 0:
                return tuple(torch.empty(0, dtype=torch.long, device=x.device) for _ in range(ndim))
            return tuple(result[:, i] for i in range(ndim))
        return result
