19	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
20	
21	at::Tensor nonzero(const at::Tensor &self, int64_t as_tuple)
22	{
23	    int64_t ndim = self.dim();
24	    int64_t totalLength = self.numel();
25	
26	    if (totalLength == 0) {
27	        return at::empty({0, ndim}, at::TensorOptions().dtype(at::kLong).device(self.device()));
28	    }
29	
30	    // Get platform info
31	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
32	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
33	    uint64_t ubSize;
34	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
35	
36	    // Contiguous input
37	    at::Tensor selfContiguous = self.contiguous();
38	    int64_t dtypeSize = selfContiguous.element_size();
39	
40	    // ---- Block level tiling ----
41	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
42	    int64_t totalLengthCoreAlign = ((totalLengthCore * dtypeSize + CACHE_LINE_BYTE_LENGTH - 1)
43	                                     / CACHE_LINE_BYTE_LENGTH) * CACHE_LINE_BYTE_LENGTH;
44	    int64_t usedCoreNum = (totalLength * dtypeSize + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
45	    if (usedCoreNum > coreNum) usedCoreNum = coreNum;
46	    if (usedCoreNum < 1) usedCoreNum = 1;
47	
48	    int64_t formerNum = usedCoreNum - 1;
49	    if (formerNum < 0) formerNum = 0;
50	    int64_t tailNum = 1;
51	    int64_t formerLength = totalLengthCoreAlign / dtypeSize;
52	    int64_t tailLength = totalLength - formerNum * formerLength;
53	    if (tailLength < 0) {
54	        tailLength = 0;
55	        tailNum = 0;
56	    }
57	
58	    // ---- Phase 1: Count nonzero elements on CPU ----
59	    auto selfCpu = selfContiguous.to(at::kCPU);
60	    int64_t nonzeroCount = 0;
61	
62	    AT_DISPATCH_ALL_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16,
63	        selfCpu.scalar_type(), "nonzero_count", [&]() {
64	        scalar_t* data = selfCpu.data_ptr<scalar_t>();
65	        for (int64_t i = 0; i < totalLength; i++) {
66	            if (data[i] != scalar_t(0)) {
67	                nonzeroCount++;
68	            }
69	        }
70	    });
71	
72	    // ---- Allocate output ----
73	    auto output = at::empty({nonzeroCount, ndim},
74	                             at::TensorOptions().dtype(at::kLong).device(self.device()));
75	
76	    if (nonzeroCount == 0) {
77	        return output;
78	    }
79	
80	    // ---- Compute per-core counts and offsets ----
81	    std::vector<int64_t> coreCounts(usedCoreNum, 0);
82	    std::vector<int64_t> coreOffsets(usedCoreNum, 0);
83	
84	    AT_DISPATCH_ALL_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16,
85	        selfCpu.scalar_type(), "nonzero_per_core_count", [&]() {
86	        scalar_t* data = selfCpu.data_ptr<scalar_t>();
87	        for (int64_t c = 0; c < usedCoreNum; c++) {
88	            int64_t start = (c < formerNum) ? c * formerLength
89	                                             : formerNum * formerLength + (c - formerNum) * tailLength;
90	            int64_t len = (c < formerNum) ? formerLength : tailLength;
91	            if (start >= totalLength) {
92	                coreCounts[c] = 0;
93	                continue;
94	            }
95	            if (start + len > totalLength) {
96	                len = totalLength - start;
97	            }
98	            int64_t count = 0;
99	            for (int64_t i = start; i < start + len; i++) {
100	                if (data[i] != scalar_t(0)) count++;
101	            }
102	            coreCounts[c] = count;
103	        }
104	    });
105	
106	    // Prefix sum for offsets
107	    int64_t offset = 0;
108	    for (int64_t c = 0; c < usedCoreNum; c++) {
109	        coreOffsets[c] = offset;
110	        offset += coreCounts[c];
111	    }
112	
113	    // ---- UB level tiling ----
114	    int64_t bufferCoefficient = 2;
115	    int64_t maxTileElements = static_cast<int64_t>(ubSize) / dtypeSize / bufferCoefficient;
116	    int64_t alignElements = 32 / dtypeSize;
117	    if (alignElements < 1) alignElements = 1;
118	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
119	    if (tileLength < 1) tileLength = 1;
120	
121	    // ---- Workspace: store shape info and offsets ----
122	    int64_t workspaceInts = 8 + usedCoreNum;  // shape[8] + offsets[usedCoreNum]
123	    int64_t workspaceSize = workspaceInts * sizeof(int64_t);
124	    auto workspace = at::empty({workspaceSize},
125	                               at::TensorOptions().dtype(at::kByte).device(self.device()));
126	    auto workspaceCpu = at::empty({workspaceSize}, at::TensorOptions().dtype(at::kByte));
127	    int64_t* workspaceData = reinterpret_cast<int64_t*>(workspaceCpu.data_ptr<uint8_t>());
128	    for (int64_t i = 0; i < ndim; i++) {
129	        workspaceData[i] = selfContiguous.size(i);
130	    }
131	    for (int64_t i = ndim; i < 8; i++) {
132	        workspaceData[i] = 1;
133	    }
134	    for (int64_t c = 0; c < usedCoreNum; c++) {
135	        workspaceData[8 + c] = coreOffsets[c];
136	    }
137	    workspace.copy_(workspaceCpu);
138	
139	    // ---- Launch Kernel ----
140	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
141	    if (blockDim < 1) blockDim = 1;
142	
143	    int64_t totalLengthL = totalLength;
144	    int64_t ndimL = ndim;
145	    int64_t formerNumL = formerNum;
146	    int64_t formerLengthL = formerLength;
147	    int64_t tailNumL = tailNum;
148	    int64_t tailLengthL = tailLength;
149	    int64_t tileLengthL = tileLength;
150	
151	    EXEC_KERNEL_CMD(nonzero, blockDim, selfContiguous, output, workspace,
152	                    totalLengthL, ndimL, formerNumL, formerLengthL,
153	                    tailNumL, tailLengthL, tileLengthL);
154	
155	    return output;
156	}
