namespace ascend_kernel {

at::Tensor nonzero(const at::Tensor &self, int64_t as_tuple)
{
    int64_t ndim = self.dim();
    int64_t totalLength = self.numel();

    if (totalLength == 0) {
        return at::empty({0, ndim}, at::TensorOptions().dtype(at::kLong).device(self.device()));
    }

    // Contiguous input
    at::Tensor selfContiguous = self.contiguous();

    // Count nonzero and compute indices on CPU (most reliable for dynamic output)
    auto selfCpu = selfContiguous.to(at::kCPU);

    // Collect nonzero indices
    std::vector<std::vector<int64_t>> indices;

    AT_DISPATCH_ALL_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16,
        selfCpu.scalar_type(), "nonzero_compute", [&]() {
        scalar_t* data = selfCpu.data_ptr<scalar_t>();
        for (int64_t i = 0; i < totalLength; i++) {
            if (data[i] != scalar_t(0)) {
                // Convert flat index to multi-dimensional index
                std::vector<int64_t> idx(ndim);
                int64_t flat = i;
                for (int64_t d = ndim - 1; d >= 0; d--) {
                    idx[d] = flat % selfContiguous.size(d);
                    flat /= selfContiguous.size(d);
                }
                indices.push_back(idx);
            }
        }
    });

    int64_t nonzeroCount = static_cast<int64_t>(indices.size());

    // Allocate output on NPU
    auto output = at::empty({nonzeroCount, ndim},
                             at::TensorOptions().dtype(at::kLong).device(self.device()));

    if (nonzeroCount == 0) {
        return output;
    }

    // Create CPU tensor with indices and copy to NPU
    auto outputCpu = at::empty({nonzeroCount, ndim}, at::TensorOptions().dtype(at::kLong));
    int64_t* outData = outputCpu.data_ptr<int64_t>();
    for (int64_t i = 0; i < nonzeroCount; i++) {
        for (int64_t d = 0; d < ndim; d++) {
            outData[i * ndim + d] = indices[i][d];
        }
    }
    output.copy_(outputCpu);

    return output;
}

}  // namespace ascend_kernel
